const path = require('path')
for (const dir of process.argv.slice(2)) {
  const r = JSON.parse(fs.readFileSync(path.join(dir, 'result.json'), 'utf8'))
  const res = r.result
  console.log('==', path.basename(dir), 'plan', r.plan, 'digest', res.digest.slice(0, 12), 'delta', res.delta, 'interval', JSON.stringify(res.interval), 'verdict', res.verdict, 'seedsPaired', res.seedsPaired)
  console.log('   thresholds', JSON.stringify(res.thresholds), 'errors', res.errors.length, 'statistic' in res ? res.statistic : '(no statistic)')
  for (const c of res.cells) {
    console.log('  ', c.environment.padEnd(34), 'pairs', c.pairs, 'unpaired', c.unpaired, 'base', c.baselineRate, 'cand', c.candidateRate, 'delta', c.delta, 'iv', JSON.stringify(c.interval))
  }
}

