const fs = require('fs')
const path = require('path')
for (const dir of process.argv.slice(2)) {
  const result = JSON.parse(fs.readFileSync(path.join(dir, 'result.json'), 'utf8')).result
  const facts = fs.readFileSync(path.join(dir, 'facts.jsonl'), 'utf8').split('\n').filter(Boolean).map(line => JSON.parse(line))
  const byKey = new Map()
  let foreign = 0
  for (const fact of facts) {
    const env = fact.identity.environment
    const match = /^experiment-([0-9a-f]{64})-(baseline|candidate)$/.exec(env.group)
    if (!match || match[1] !== result.digest) { foreign += 1; continue }
    const key = `${env.environmentId}#${env.repetition}#${match[2]}`
    if (byKey.has(key)) throw new Error('duplicate ' + key)
    byKey.set(key, fact.outcome.certified === true)
  }
  console.log('==', path.basename(dir), 'facts', facts.length, 'foreign', foreign)
  for (const cell of result.cells) {
    const deltas = []
    let b = 0, c = 0
    for (let r = 0; r < 2; r += 1) {
      const base = byKey.get(`${cell.environment}#${r}#baseline`)
      const cand = byKey.get(`${cell.environment}#${r}#candidate`)
      if (base === undefined || cand === undefined) continue
      deltas.push(Number(cand) - Number(base))
      b += Number(base); c += Number(cand)
    }
    const ok = deltas.length === cell.pairs && b === Math.round(cell.baselineRate * cell.pairs) && c === Math.round(cell.candidateRate * cell.pairs)
    console.log('  ', cell.environment.padEnd(22), 'deltas', JSON.stringify(deltas).padEnd(8), 'b', b, 'c', c, ok ? 'match' : 'MISMATCH', 'recorded iv', JSON.stringify(cell.interval))
  }
}

