const fs = require('fs')
for (const file of process.argv.slice(2)) {
  const text = fs.readFileSync(file, 'utf8')
  const ok = text.endsWith('\n') && !text.endsWith('\n\n')
  const trailing = text.split('\n').filter(line => / +$/.test(line)).length
  console.log(`${ok ? 'ok ' : 'BAD'} eol, ${trailing} trailing-space lines: ${file}`)
}

